const state={dashboard:null,campaigns:[],definition:null,responses:[],hydrated:[],tab:"global",selected:null,mode:"view",loaded:null,config:null};
function active(r){const v=Object.prototype.hasOwnProperty.call(r??{},"Actif")?r.Actif:r?.Active;return v===undefined||v===null||v===""||isTrue(v)}
function first(row,names,fallback=""){for(const n of names)if(row?.[n]!=null&&row[n]!=="")return row[n];return fallback}
function escapeHtml(v=""){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function resolveRefCode(value,rows,codeColumn){const raw=codeOf(value);if(!raw)return"";const byId=(rows??[]).find(r=>String(r.id)===String(raw));return byId?codeOf(byId[codeColumn]):raw}
function labelStyle(){return""}
function param(name){for(const raw of [globalThis.location?.href,globalThis.document?.referrer].filter(Boolean)){try{const v=String(new URL(raw).searchParams.get(name)||"").trim();if(v)return v}catch{}}return""}
async function fetch(name){return rowsFromTable(await grist.docApi.fetchTable(name))}
async function fetchDashboardTable(){
  try{return await fetch("DASHBOARDS")}catch(firstError){
    try{
      const meta=await fetch("_grist_Tables");
      const ids=meta.map(r=>String(r.tableId||"")).filter(Boolean);
      const exact=ids.find(id=>id.toUpperCase()==="DASHBOARDS");
      const candidates=ids.filter(id=>id.toUpperCase().startsWith("DASHBOARDS"));
      const tableId=exact||(candidates.length===1?candidates[0]:"");
      if(tableId)return await fetch(tableId);
      const hint=candidates.length?` Tables proches détectées : ${candidates.join(", ")}.`:"";
      throw new Error(`La table DASHBOARDS est introuvable dans Grist.${hint}`);
    }catch(metaError){
      if(metaError?.message?.startsWith("La table DASHBOARDS"))throw metaError;
      throw new Error(`Impossible d’accéder à la table DASHBOARDS. Vérifiez son identifiant technique dans Données brutes. (${firstError?.message||firstError})`);
    }
  }
}
function sameRef(v,row,col){const raw=codeOf(v);return raw===String(row?.id)||raw===codeOf(row?.[col])}
function campaignGroup(c){return String(c?.Groupe_Campagne_Code||codeOf(c?.Campagne_Code)||c?.id||"")}
