function questionChoiceLabels(q){
  const out=new Map(),def=state.definition||{},qc=String(codeOf(q?.Question_Code)||"");
  for(const c of def.choices||[]){
    if(String(resolveRefCode(c.Question_Code,def.questions||[],"Question_Code"))!==qc)continue;
    const k=String(codeOf(c.Choix_Code)||"");
    if(k)out.set(k,String(first(c,["Libelle","Libellé","Valeur","Choix_Code"],k)));
  }
  const rc=resolveRefCode(q?.Referentiel_Code,def.referentials||[],"Referentiel_Code");
  if(rc){
    const ref=(def.referentials||[]).find(r=>String(codeOf(r.Referentiel_Code))===String(rc));
    const source=String(ref?.Type_source||"VALEURS_REFERENTIELS").trim().toUpperCase();
    if(source==="STRUCTURES"){
      for(const r of def.structures||[]){const k=String(codeOf(r.Structure_Code)||"");if(k)out.set(k,String(first(r,["Nom","Libelle","Libellé","Structure_Code"],k)));}
    }else{
      for(const r of def.referentialValues||[]){
        if(String(resolveRefCode(r.Referentiel_Code,def.referentials||[],"Referentiel_Code"))!==String(rc))continue;
        const k=String(codeOf(r.ValeurRef_Code)||"");
        if(k)out.set(k,String(first(r,["Libelle","Libellé","Valeur","ValeurRef_Code"],k)));
      }
    }
  }
  return out;
}
