function configuredIndicatorBlocks(){return (state.definition?.questions||[]).filter(q=>String(first(q,["Type_question","Type_reponse","Type","Format"],"")).trim().toLowerCase()==="indicateurs"&&active(q))}
function responseLabel(h,i){const r=h.response||{};const c=state.campaigns.find(x=>sameRef(r.Campagne_Code,x,"Campagne_Code"));return String(c?.Valeur_personnalisation_Libelle||c?.Valeur_personnalisation||r.Nom_repondant||r.Repondant||`Réponse ${i+1}`)}
function scalarDisplay(v,q){if(Array.isArray(v))return v.map(x=>indicatorGroupLabel(q,x)).join(", ");if(v==null||v==="")return"—";return indicatorNumeric(q)?String(v):indicatorGroupLabel(q,v)}
function selectedTokens(){const out=[];for(const b of configuredIndicatorBlocks())for(const t of indicatorQuestionCodes(b))if(!out.includes(t))out.push(t);return out}
function tokenTitle(t){if(t.startsWith("f:")){const f=indicatorFicheType(t.slice(2));return f?`Nb ${ficheLabel(f)}`:t}if(t.startsWith("fq:")){const r=t.slice(3),i=r.indexOf(":"),fc=r.slice(0,i),qc=r.slice(i+1),q=indicatorFicheQuestion(qc,fc);return q?questionLabel(q):t}const qc=t.startsWith("q:")?t.slice(2):t,q=(state.definition?.questions||[]).find(x=>codeOf(x.Question_Code)===qc);return q?questionLabel(q):t}
function responseTokenValue(h,t){if(t.startsWith("f:"))return (h.fiches?.[t.slice(2)]||[]).length;if(t.startsWith("fq:")){const r=t.slice(3),i=r.indexOf(":"),fc=r.slice(0,i),qc=r.slice(i+1),q=indicatorFicheQuestion(qc,fc),vals=(h.fiches?.[fc]||[]).map(x=>x.answers?.[qc]).filter(v=>v!==undefined&&v!==null&&v!=="");if(!vals.length)return"—";if(q&&indicatorNumeric(q))return vals.map(Number).filter(Number.isFinite).reduce((a,b)=>a+b,0);return [...new Set(vals.flatMap(v=>Array.isArray(v)?v:[v]).map(v=>indicatorGroupLabel(q,v)))].join(", ")}const qc=t.startsWith("q:")?t.slice(2):t,q=(state.definition?.questions||[]).find(x=>codeOf(x.Question_Code)===qc);return scalarDisplay(h.principalAnswers?.[qc],q)}
function renderHeader(){const d=state.dashboard,c=state.campaigns[0];return `<div class="dash-head"><div><h1>${escapeHtml(d?.Nom||"Tableau de bord")}</h1><div class="muted">${escapeHtml(c?.Nom||"Campagne")} · ${state.responses.length} réponse(s)</div></div><div class="dashboard-view-actions"><button type="button" data-print-current>Imprimer / PDF cet onglet</button><button type="button" data-print-all>Imprimer / PDF tout le Dashboard</button><button type="button" data-export-dashboard>Exporter les données</button></div></div>`}
function renderGlobal(){const blocks=configuredIndicatorBlocks();return `<div class="dash-kpis"><div class="dash-kpi"><span>Réponses</span><strong>${state.responses.length}</strong></div><div class="dash-kpi"><span>Blocs d’indicateurs</span><strong>${blocks.length}</strong></div></div><div class="dash-grid" style="margin-top:14px">${blocks.map(renderIndicators).join("")||'<div class="dash-card">Aucun bloc Indicateurs n’est configuré dans cette version.</div>'}</div>`}
function renderParticipants(){const tokens=selectedTokens();return `<div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Répondant</th><th>Statut</th>${tokens.map(t=>`<th>${escapeHtml(tokenTitle(t))}</th>`).join("")}</tr></thead><tbody>${state.hydrated.map((h,i)=>`<tr data-response="${i}"><td><strong>${escapeHtml(responseLabel(h,i))}</strong></td><td>${escapeHtml(String(h.response?.Statut||"—"))}</td>${tokens.map(t=>`<td>${escapeHtml(String(responseTokenValue(h,t)))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function renderDetail(i){const h=state.hydrated[i];if(!h)return"";const main=(state.definition?.questions||[]).filter(q=>active(q)&&!resolveRefCode(q.TypeFiche_Code,state.definition?.ficheTypes||[],"TypeFiche_Code")&&!['description','sommaire','indicateurs','tableau_donnees'].includes(String(first(q,["Type_question","Type"],"")).toLowerCase()));const ficheCards=(state.definition?.ficheTypes||[]).map(ft=>{const fc=codeOf(ft.TypeFiche_Code),rows=h.fiches?.[fc]||[];if(!rows.length)return"";return `<div class="dash-card"><h3>${escapeHtml(ficheLabel(ft))} (${rows.length})</h3>${rows.map((r,n)=>`<div style="margin:10px 0;padding-top:8px;border-top:1px solid #eee"><strong>#${n+1}</strong>${(state.definition.questions||[]).filter(q=>resolveRefCode(q.TypeFiche_Code,state.definition.ficheTypes,"TypeFiche_Code")===fc).map(q=>`<div class="answer-row"><strong>${escapeHtml(questionLabel(q))}</strong>${escapeHtml(scalarDisplay(r.answers?.[codeOf(q.Question_Code)],q))}</div>`).join("")}</div>`).join("")}</div>`}).join("");return `<button class="back-btn" data-back>← Retour aux répondants</button><h2>${escapeHtml(responseLabel(h,i))}</h2><div class="participant-detail-grid"><div class="dash-card"><h3>Réponse principale</h3>${main.map(q=>`<div class="answer-row"><strong>${escapeHtml(questionLabel(q))}</strong>${escapeHtml(scalarDisplay(h.principalAnswers?.[codeOf(q.Question_Code)],q))}</div>`).join("")}</div>${ficheCards}</div>`}
function csvCell(v){const s=String(v??"").replace(/\r?\n/g," ");return /[;"\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
function dashboardExportRows(){const rows=[["Dashboard",state.dashboard?.Nom||"Tableau de bord"],["Campagne",state.campaigns?.[0]?.Nom||""],["Réponses",state.responses.length],[]],root=document.querySelector('#root');const panels=[...root.querySelectorAll('[data-view-tab-panel]')],targets=panels.length?panels:[root];targets.forEach((panel,pi)=>{const tabId=panel.dataset?.viewTabPanel||"",btn=tabId?root.querySelector(`[data-view-tab="${CSS.escape(tabId)}"]`):null;rows.push([btn?.textContent?.trim()||`Vue ${pi+1}`]);panel.querySelectorAll('.dash-kpi').forEach(k=>rows.push([k.querySelector('span')?.textContent?.trim()||"Indicateur",k.querySelector('strong')?.textContent?.trim()||""]));panel.querySelectorAll('.indicator-card,.dash-card,.dashboard-configured-block').forEach(card=>{const title=card.querySelector('h3,h4')?.textContent?.trim();if(title)rows.push([title]);card.querySelectorAll('table').forEach(table=>{[...table.rows].forEach(tr=>rows.push([...tr.cells].map(td=>td.textContent.trim())));rows.push([])});card.querySelectorAll('.metric-table>div').forEach(line=>rows.push([...line.children].map(x=>x.textContent.trim())));rows.push([])});rows.push([])});return rows}
function exportDashboardData(){const csv="sep=;\r\n"+dashboardExportRows().map(r=>r.map(csvCell).join(";")).join("\r\n"),blob=new Blob(["\ufeff",csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a"),name=String(state.dashboard?.Nom||"dashboard").replace(/[<>:"/\\\\|?*]+/g,"_").trim()||"dashboard";a.href=url;a.download=`${name}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printDashboard(all=false){document.body.classList.toggle('dashboard-print-all',all);const done=()=>{document.body.classList.remove('dashboard-print-all');window.removeEventListener('afterprint',done)};window.addEventListener('afterprint',done);window.print()}
function bind(){document.querySelector('[data-print-current]')?.addEventListener('click',()=>printDashboard(false));document.querySelector('[data-print-all]')?.addEventListener('click',()=>printDashboard(true));document.querySelector('[data-export-dashboard]')?.addEventListener('click',exportDashboardData);document.querySelectorAll('[data-response]').forEach(r=>r.onclick=()=>{state.selected=Number(r.dataset.response);render()});document.querySelector('[data-back]')?.addEventListener('click',()=>{state.selected=null;render()})}
function render(){const root=document.querySelector('#root');root.innerHTML=renderHeader()+(state.selected!=null?renderDetail(state.selected):renderGlobal());bind()}
async function loadViewer(){const loaded={};for(const t of TABLES){if(t==="DASHBOARDS")loaded[t]=await fetchDashboardTable();else loaded[t]=await fetch(t)}state.loaded=loaded;const token=param('Dashboard_');let d=token?loaded.DASHBOARDS.find(x=>active(x)&&String(x.Jeton_acces||x.Jeton_dashboard||"")===token):null;if(!d&&loaded.DASHBOARDS.filter(active).length===1)d=loaded.DASHBOARDS.filter(active)[0];if(!d)throw new Error('Tableau de bord introuvable ou non autorisé.');state.dashboard=d;const campaignRaw=codeOf(d.Campagne_Code);const directCampaign=loaded.CAMPAGNES.find(c=>active(c)&&(String(c.id)===String(campaignRaw)||String(codeOf(c.Campagne_Code))===String(campaignRaw)));const groupRaw=directCampaign?campaignGroup(directCampaign):String(campaignRaw||"");state.campaigns=loaded.CAMPAGNES.filter(c=>active(c)&&(campaignGroup(c)===groupRaw||String(c.id)===String(campaignRaw)||String(codeOf(c.Campagne_Code))===String(campaignRaw)));if(!state.campaigns.length)throw new Error('La campagne associée à ce tableau de bord est inaccessible. Vérifiez DASHBOARDS.Campagne_Code avec le Code campagne (groupe) affiché dans le Concepteur.');const vraw=codeOf(state.campaigns[0].Version_Code),version=loaded.VERSIONS_QUESTIONNAIRES.find(v=>String(v.id)===vraw||codeOf(v.Version_Code)===vraw);if(!version)throw new Error('Version du questionnaire inaccessible.');const vc=codeOf(version.Version_Code),byVersion=rows=>rows.filter(r=>!('Version_Code' in r)||resolveRefCode(r.Version_Code,loaded.VERSIONS_QUESTIONNAIRES,'Version_Code')===vc);state.definition={version,questions:byVersion(loaded.QUESTIONS).filter(active),ficheTypes:byVersion(loaded.TYPES_FICHES).filter(active),choices:loaded.CHOIX_QUESTIONS.filter(active),referentials:loaded.REFERENTIELS.filter(active),referentialValues:loaded.VALEURS_REFERENTIELS.filter(active),structures:loaded.STRUCTURES.filter(active),responses:loaded.REPONSES,responseElements:loaded.ELEMENTS_REPONSE,responseValues:loaded.VALEURS_REPONSE,responseSelections:loaded.SELECTIONS_REPONSE};const ids=new Set(state.campaigns.flatMap(c=>[String(c.id),codeOf(c.Campagne_Code)]));state.responses=loaded.REPONSES.filter(r=>!isTrue(r.Supprime_logiquement)&&ids.has(codeOf(r.Campagne_Code)));const tables={REPONSES:loaded.REPONSES,ELEMENTS_REPONSE:loaded.ELEMENTS_REPONSE,VALEURS_REPONSE:loaded.VALEURS_REPONSE,SELECTIONS_REPONSE:loaded.SELECTIONS_REPONSE};state.hydrated=state.responses.map(r=>hydrateResponse(tables,state.definition,codeOf(r.Reponse_Code)||String(r.id))).filter(h=>h.response);document.querySelector('#status').innerHTML='';render()}

function dashboardConfig(row){try{const x=JSON.parse(String(row?.Configuration_JSON||"{}"));return x&&typeof x==="object"&&!Array.isArray(x)?x:{blocks:[]}}catch{return{blocks:[]}}}
function dashboardGroupRows(rows){const m=new Map;for(const c of rows.filter(active)){const g=campaignGroup(c);if(!g)continue;if(!m.has(g))m.set(g,[]);m.get(g).push(c)}return [...m].map(([code,rows])=>({code,rows,first:rows[0],name:String(first(rows[0],["Nom","Libelle","Libellé"],code))})).sort((a,b)=>a.name.localeCompare(b.name,"fr"))}
function uid(prefix){return `${prefix}_${Date.now().toString(36).toUpperCase()}_${Math.random().toString(36).slice(2,7).toUpperCase()}`}
async function ensureDashboardConfigColumn(){try{await grist.docApi.applyUserActions([["AddColumn","DASHBOARDS","Configuration_JSON",{type:"Text"}]])}catch(e){const m=String(e?.message||e).toLowerCase();if(!/exist|duplicate|already|column/.test(m))throw e}}
async function reloadDashboardRows(){state.loaded.DASHBOARDS=await fetchDashboardTable()}
function builderCampaignVersion(group){const c=group?.first;if(!c)return null;const raw=codeOf(c.Version_Code);return (state.loaded.VERSIONS_QUESTIONNAIRES||[]).find(v=>String(v.id)===String(raw)||String(codeOf(v.Version_Code))===String(raw))||null}
function versionQuestions(group){const v=builderCampaignVersion(group);if(!v)return[];const vc=codeOf(v.Version_Code);return (state.loaded.QUESTIONS||[]).filter(q=>active(q)&&resolveRefCode(q.Version_Code,state.loaded.VERSIONS_QUESTIONNAIRES||[],"Version_Code")===vc)}
function versionFicheTypes(group){const v=builderCampaignVersion(group);if(!v)return[];const vc=codeOf(v.Version_Code);return (state.loaded.TYPES_FICHES||[]).filter(f=>active(f)&&resolveRefCode(f.Version_Code,state.loaded.VERSIONS_QUESTIONNAIRES||[],"Version_Code")===vc)}
function builderIndicatorBlocks(group){return versionQuestions(group).filter(q=>String(first(q,["Type_question","Type_reponse","Type","Format"],"")).trim().toLowerCase()==="indicateurs")}
function builderRow(id){return (state.loaded.DASHBOARDS||[]).find(r=>String(r.id)===String(id))}
function usableQuestion(q){return !["description","sommaire","indicateurs","tableau_donnees"].includes(indicatorQuestionType(q))}
function sourceOptions(group){const qs=versionQuestions(group).filter(usableQuestion),fts=versionFicheTypes(group),out=[];for(const q of qs){const fc=resolveRefCode(q.TypeFiche_Code,fts,"TypeFiche_Code");const qc=codeOf(q.Question_Code);if(!qc)continue;out.push({token:fc?`fq:${fc}:${qc}`:`q:${qc}`,label:fc?`${ficheLabel(fts.find(f=>codeOf(f.TypeFiche_Code)===fc)||{})} — ${questionLabel(q)}`:questionLabel(q),q,kind:fc?"fq":"q",typeCode:fc})}for(const ft of fts){const fc=codeOf(ft.TypeFiche_Code);if(fc)out.push({token:`f:${fc}`,label:`Nombre de ${first(ft,["Libelle_pluriel","Libellé_pluriel","Libelle_singulier","Libellé_singulier","Libelle","Nom"],fc)}`,ft,kind:"f",typeCode:fc})}return out.sort((a,b)=>a.label.localeCompare(b.label,"fr"))}
function sourceByToken(group,token){return sourceOptions(group).find(x=>x.token===token)||null}
function ventilationOptions(group,sourceToken){const all=sourceOptions(group),src=all.find(x=>x.token===sourceToken);if(!src)return[];const questions=all.filter(x=>x.kind==="q"||x.kind==="fq");if(src.kind==="q")return questions;if(src.kind==="fq")return questions.filter(x=>x.kind==="q"||x.typeCode===src.typeCode||indicatorIsDescendantFicheType(x.typeCode,src.typeCode)||indicatorIsDescendantFicheType(src.typeCode,x.typeCode));if(src.kind==="f")return questions.filter(x=>x.kind==="q"||(x.kind==="fq"&&(x.typeCode===src.typeCode||indicatorIsDescendantFicheType(x.typeCode,src.typeCode))));return[]}
function defaultStatsForSource(src){if(src?.kind==="f")return["total"];if(src?.q&&indicatorNumeric(src.q))return["count","sum","mean"];return["count","percent"]}
function statChoices(src){if(src?.kind==="f")return [["total","Nombre total"],["withAny","Répondants avec au moins une fiche"],["mean","Moyenne par répondant"],["min","Minimum"],["max","Maximum"]];if(src?.q&&indicatorNumeric(src.q))return [["count","Nombre de valeurs"],["sum","Somme"],["mean","Moyenne"],["median","Médiane"],["min","Minimum"],["max","Maximum"]];return [["count","Nombre"],["percent","Pourcentage"]]}
function builderBlockFromElement(el,i){const type=el.dataset.blockType,b={id:el.dataset.blockId,type,order:i+1,title:el.querySelector('[data-block-title]')?.value||""};if(type==="text")b.text=el.querySelector('[data-block-text]')?.value||"";else if(type==="reuse"){b.indicatorCode=el.querySelector('[data-block-indicator]')?.value||"";b.display=el.querySelector('[data-block-display]')?.value||"inherit"}else if(type==="indicator"){b.source=el.querySelector('[data-source]')?.value||"";b.scope=el.querySelector('[data-scope]')?.value||"global";b.groupBy=el.querySelector('[data-group-by]')?.value||"";b.display=el.querySelector('[data-block-display]')?.value||"both";b.chart=el.querySelector('[data-chart]')?.value||"bar";b.globalLabel=el.querySelector('[data-global-label]')?.value||"";b.ventilationLabel=el.querySelector('[data-ventilation-label]')?.value||"";b.showTotalRow=Boolean(el.querySelector('[data-show-total-row]')?.checked);b.stats=[...el.querySelectorAll('[data-stat]:checked')].map(x=>x.value)}return b}
function normalizeDashboardTabs(config={}){if(Array.isArray(config.tabs)&&config.tabs.length)return config.tabs.map((t,i)=>({id:t.id||uid('TAB'),title:t.title||`Onglet ${i+1}`,order:t.order||i+1,blocks:Array.isArray(t.blocks)?t.blocks:[]}));return[{id:uid('TAB'),title:"Vue globale",order:1,blocks:Array.isArray(config.blocks)?config.blocks:[]}]}
function builderConfigFromForm(){const tabs=[...document.querySelectorAll('[data-dashboard-tab]')].map((tab,i)=>({id:tab.dataset.tabId,title:tab.querySelector('[data-tab-title]')?.value||`Onglet ${i+1}`,order:i+1,blocks:[...tab.querySelectorAll('[data-builder-block]')].map(builderBlockFromElement)}));return{version:4,groupings:builderGroupingsFromForm(),tabs}}
function optionHtml(items,value,placeholder="— Sélectionner —"){return `<option value="">${placeholder}</option>${items.map(x=>`<option value="${escapeHtml(x.token??x.value)}" ${String(value||"")===String(x.token??x.value)?"selected":""}>${escapeHtml(x.label)}</option>`).join("")}`}
function builderBlockHtml(b,group){const type=b.type||"text",id=b.id||uid('B'),head=type==="text"?"Texte":type==="respondents"?"Répondants":type==="reuse"?"Indicateur existant":"Indicateur Dashboard",summary=String(b.title||head),common=`<div class="builder-block-head"><strong>${head}</strong><div><button type="button" data-move-up>↑</button><button type="button" data-move-down>↓</button><button type="button" data-remove-block>Supprimer</button></div></div><label>Titre du bloc<input data-block-title value="${escapeHtml(b.title||"")}"></label>`;let body="";if(type==="respondents")body=`<div class="help">Affiche le nombre de réponses consolidées de la campagne.</div>`;else if(type==="text")body=`<label>Texte<textarea data-block-text rows="5">${escapeHtml(b.text||"")}</textarea></label>`;else if(type==="reuse"){const inds=builderIndicatorBlocks(group);body=`<label>Indicateur du questionnaire<select data-block-indicator><option value="">— Sélectionner —</option>${inds.map(q=>`<option value="${escapeHtml(codeOf(q.Question_Code))}" ${String(b.indicatorCode||"")===String(codeOf(q.Question_Code))?"selected":""}>${escapeHtml(questionLabel(q))}</option>`).join("")}</select></label><label>Affichage<select data-block-display><option value="inherit" ${b.display==="inherit"||!b.display?"selected":""}>Réglage de l’indicateur</option><option value="both" ${b.display==="both"?"selected":""}>Tableau + graphique</option><option value="chart" ${b.display==="chart"?"selected":""}>Graphique uniquement</option><option value="table" ${b.display==="table"?"selected":""}>Tableau uniquement</option></select></label>`}else{const sources=sourceOptions(group),src=sourceByToken(group,b.source),vents=[...ventilationOptions(group,b.source),...dashboardGroupingOptions(group,b.source)],stats=statChoices(src),chosen=new Set(b.stats?.length?b.stats:defaultStatsForSource(src));body=`<div class="builder-indicator-grid"><label>Question / donnée analysée<select data-source>${optionHtml(sources,b.source)}</select></label><label>Résultat<select data-scope><option value="global" ${b.scope==="global"||!b.scope?"selected":""}>Global uniquement</option><option value="ventilation" ${b.scope==="ventilation"?"selected":""}>Ventilation uniquement</option><option value="both" ${b.scope==="both"?"selected":""}>Global + ventilation</option></select></label><label class="group-field">Ventilation par<select data-group-by>${optionHtml(vents,b.groupBy)}</select></label><label>Affichage<select data-block-display><option value="both" ${b.display==="both"||!b.display?"selected":""}>Tableau + graphique</option><option value="chart" ${b.display==="chart"?"selected":""}>Graphique uniquement</option><option value="table" ${b.display==="table"?"selected":""}>Tableau uniquement</option></select></label><label>Graphique<select data-chart><option value="bar" ${b.chart==="bar"||!b.chart?"selected":""}>Barres</option><option value="pie" ${b.chart==="pie"?"selected":""}>Camembert</option><option value="none" ${b.chart==="none"?"selected":""}>Aucun</option></select></label><label>Libellé du résultat global<input data-global-label placeholder="Global" value="${escapeHtml(b.globalLabel||"")}"></label><label>Libellé de la ventilation<input data-ventilation-label placeholder="Ventilation par …" value="${escapeHtml(b.ventilationLabel||"")}"></label></div><div class="stats-box"><strong>Calculs</strong><div class="stats-checks">${stats.map(([v,l])=>`<label><input type="checkbox" data-stat value="${v}" ${chosen.has(v)?"checked":""}> ${escapeHtml(l)}</label>`).join("")||'<span class="help">Choisissez d’abord une question.</span>'}</div><label class="check"><input type="checkbox" data-show-total-row ${b.showTotalRow?"checked":""}> Afficher une ligne Total dans le tableau</label></div>`}return `<details class="builder-block" data-builder-block data-block-id="${escapeHtml(id)}" data-block-type="${escapeHtml(type)}"><summary class="builder-collapse-summary"><span><strong data-block-summary-title>${escapeHtml(summary)}</strong><small>${escapeHtml(head)}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-block-body">${common}${body}</div></details>`}
const DASHBOARD_CONSULTATION_PAGE="https://grist.numerique.gouv.fr/o/docs/wquFLHYyyedo/Gristionnaire/p/50";
function shareUrlForToken(token){if(!token)return"";try{const u=new URL(DASHBOARD_CONSULTATION_PAGE);u.searchParams.set("Dashboard_",token);u.searchParams.set("style","singlePage");return u.toString()}catch{return""}}
function currentDashboardShareUrl(row){if(!row)return"";const token=String(row.Jeton_acces||row.Jeton_dashboard||"").trim();if(!token)return"";return shareUrlForToken(token)||String(row.URL_dashboard||"").trim()}
function renderShare(row){const url=currentDashboardShareUrl(row);if(!row)return'<div class="share-card muted">Enregistrez d’abord le Dashboard pour obtenir son lien de partage.</div>';return `<div class="share-card"><div><strong>Partage</strong><div class="help">Lien de consultation du Dashboard</div></div><input id="share-url" readonly value="${escapeHtml(url||"Lien indisponible")}"><button type="button" id="copy-dashboard-link" ${url?"":"disabled"}>Copier le lien</button><button type="button" id="open-dashboard-preview" ${url?"":"disabled"}>Ouvrir la consultation</button></div>`}
const LAST_DASHBOARD_STORAGE_KEY="gristionnaire.dashboard.lastDashboardCode";
function rememberLastDashboard(row){try{const code=String(row?.Dashboard_Code||"").trim();if(code)localStorage.setItem(LAST_DASHBOARD_STORAGE_KEY,code)}catch(_){}}
function restoreLastDashboardSelection(){let code="";try{code=String(localStorage.getItem(LAST_DASHBOARD_STORAGE_KEY)||"").trim()}catch(_){}if(!code)return;const row=(state.loaded.DASHBOARDS||[]).filter(active).find(r=>String(r.Dashboard_Code||"").trim()===code);const sel=document.querySelector('#builder-dashboard');if(row&&sel){sel.value=String(row.id);sel.dispatchEvent(new Event('change'))}}
function renderBuilder(){const root=document.querySelector('#root'),groups=dashboardGroupRows(state.loaded.CAMPAGNES||[]),rows=(state.loaded.DASHBOARDS||[]).filter(active);root.innerHTML=`<div class="builder-shell"><div class="dash-head builder-page-head"><div><h1>Constructeur de Dashboard</h1><div class="muted">Configurez le tableau de bord, préparez vos regroupements puis construisez les onglets de restitution.</div></div><div class="builder-main-actions"><button type="button" id="preview-dashboard">Aperçu</button><button type="button" class="primary" id="save-dashboard">Enregistrer</button></div></div><section class="builder-section builder-config-section"><div class="builder-section-heading"><span class="builder-step">1</span><div><h2>Configuration</h2><div class="help">Choisissez le Dashboard et la campagne auxquels vous souhaitez travailler.</div></div></div><div class="builder-toolbar builder-config-grid"><label>Dashboard<select id="builder-dashboard"><option value="new">+ Nouveau Dashboard</option>${rows.map(r=>`<option value="${r.id}">${escapeHtml(r.Nom||r.Dashboard_Code||`Dashboard ${r.id}`)}</option>`).join("")}</select></label><label>Nom du Dashboard<input id="builder-name" placeholder="Ex. Tableau de bord FDP"></label><label>Campagne<select id="builder-campaign"><option value="">— Sélectionner —</option>${groups.map(g=>`<option value="${escapeHtml(g.code)}">${escapeHtml(g.name)}</option>`).join("")}</select></label></div></section><div class="builder-secondary-grid"><details class="builder-panel"><summary><span><strong>Partage</strong><small>Lien de consultation du Dashboard</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body" id="builder-share">${renderShare(null)}</div></details><details class="builder-panel"><summary><span><strong>Regroupements</strong><small>Préparez les ventilations personnalisées</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body" id="builder-groupings"></div></details></div><section class="builder-section builder-design-section"><div class="builder-section-heading builder-design-heading"><span class="builder-step">2</span><div><h2>Conception du Dashboard</h2><div class="help">Organisez votre restitution en onglets puis ajoutez les indicateurs et contenus nécessaires.</div></div><button type="button" id="add-dashboard-tab">+ Ajouter un onglet</button></div><div id="builder-tabs"></div></section><div id="builder-preview" class="builder-preview" hidden></div></div>`;bindBuilder()}

function normalizeDashboardGroupings(config={}){return Array.isArray(config.groupings)?config.groupings.map((g,i)=>({id:g.id||uid('GRP'),name:g.name||`Regroupement ${i+1}`,source:g.source||"",fallbackSource:g.fallbackSource||"",groups:Array.isArray(g.groups)?g.groups.map((x,j)=>({id:x.id||uid('VAL'),label:x.label||`Groupe ${j+1}`,values:Array.isArray(x.values)?x.values.map(String):[]})):[]})):[]}
function groupingSourceOptions(group){return sourceOptions(group).filter(x=>x.kind==="q"||x.kind==="fq")}
function builderQuestionChoiceLabels(group,q){const out=new Map(),questions=versionQuestions(group),qc=String(codeOf(q?.Question_Code)||"");for(const c of state.loaded.CHOIX_QUESTIONS||[]){if(!active(c))continue;if(String(resolveRefCode(c.Question_Code,questions,"Question_Code"))!==qc)continue;const k=String(codeOf(c.Choix_Code)||"");if(k)out.set(k,String(first(c,["Libelle","Libellé","Valeur","Choix_Code"],k)))}const allRefs=state.loaded.REFERENTIELS||[],rc=resolveRefCode(q?.Referentiel_Code,allRefs,"Referentiel_Code");if(rc){const rawRef=codeOf(q?.Referentiel_Code),ref=allRefs.find(r=>String(r.id)===String(rawRef)||String(codeOf(r.Referentiel_Code))===String(rc)),source=String(ref?.Type_source||"VALEURS_REFERENTIELS").trim().toUpperCase();if(source==="STRUCTURES"){for(const r of(state.loaded.STRUCTURES||[]).filter(active)){const k=String(codeOf(r.Structure_Code)||"");if(k)out.set(k,String(first(r,["Nom","Libelle","Libellé","Structure_Code"],k)))}}else{for(const r of(state.loaded.VALEURS_REFERENTIELS||[]).filter(active)){if(String(resolveRefCode(r.Referentiel_Code,allRefs,"Referentiel_Code"))!==String(rc))continue;const k=String(codeOf(r.ValeurRef_Code)||"");if(k)out.set(k,String(first(r,["Libelle","Libellé","Valeur","ValeurRef_Code"],k)))}}}return out}
function groupingSourceValues(group,sourceToken){const src=sourceByToken(group,sourceToken);if(!src?.q)return[];const labels=builderQuestionChoiceLabels(group,src.q),values=new Map(labels);/* La définition de la question est la source principale : choix, référentiel ou STRUCTURES. */if(!values.size){try{for(const item of valuesForSource(src))for(const raw of nonEmptyGroups(item.value)){const key=String(codeOf(raw)||raw);if(key&&!values.has(key))values.set(key,key)}}catch(_){}}return [...values].map(([value,label])=>({value,label})).sort((a,b)=>String(a.label).localeCompare(String(b.label),"fr"))}
function groupingEditorGroupHtml(g,sourceValues){const selected=new Set((g.values||[]).map(String)),known=new Set((sourceValues||[]).map(x=>String(x.value))),allValues=[...(sourceValues||[]),...[...selected].filter(v=>!known.has(v)).map(v=>({value:v,label:v}))],label=String(g.label||"Nouveau groupe"),count=selected.size;return `<details class="dashboard-group-row" data-grouping-group data-group-id="${escapeHtml(g.id||uid('VAL'))}"><summary><span><strong data-group-summary-label>${escapeHtml(label)}</strong><small>${count} valeur${count>1?"s":""}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="dashboard-group-row-body"><label>Nom du groupe<input data-group-label value="${escapeHtml(g.label||"")}"></label><div class="dashboard-group-values"><label>Valeurs / structures à regrouper<input type="search" data-group-values-search placeholder="Rechercher une valeur…"></label><div class="dashboard-group-values-list" data-group-values-list>${allValues.map(x=>`<label class="dashboard-group-value" data-group-value-label="${escapeHtml(String(x.label).toLowerCase())}"><input type="checkbox" data-group-value value="${escapeHtml(x.value)}" ${selected.has(String(x.value))?"checked":""}><span>${escapeHtml(x.label)}</span></label>`).join("")}</div></div><div class="dashboard-group-order-actions"><button type="button" data-group-up>↑ Monter</button><button type="button" data-group-down>↓ Descendre</button><button type="button" data-remove-group>Supprimer ce groupe</button></div></div></details>`}
function groupingEditorHtml(g,group){const sources=groupingSourceOptions(group),vals=groupingSourceValues(group,g.source),src=sourceByToken(group,g.source),fallbacks=sourceOptions(group).filter(x=>x.kind==="q"),name=String(g.name||"Nouveau regroupement"),sourceLabel=src?.label||"Variable non sélectionnée",n=(g.groups||[]).length;return `<details class="dashboard-grouping-card" data-dashboard-grouping data-grouping-id="${escapeHtml(g.id||uid('GRP'))}"><summary class="dashboard-grouping-summary"><span><strong data-grouping-summary-name>${escapeHtml(name)}</strong><small>${escapeHtml(sourceLabel)} · ${n} groupe${n>1?"s":""}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="dashboard-grouping-body"><div class="builder-block-head"><strong>Paramètres du regroupement</strong><div><button type="button" data-duplicate-grouping>Dupliquer</button><button type="button" data-remove-grouping>Supprimer le regroupement</button></div></div><div class="builder-indicator-grid"><label>Nom du regroupement<input data-grouping-name placeholder="Ex. Services" value="${escapeHtml(g.name||"")}"></label><label>Variable à regrouper<select data-grouping-source>${optionHtml(sources,g.source)}</select></label>${src?.kind==="fq"?`<label>Valeur de repli si la fiche est vide<select data-grouping-fallback><option value="">— Aucun repli —</option>${fallbacks.map(x=>`<option value="${escapeHtml(x.token)}" ${String(g.fallbackSource||"")===String(x.token)?"selected":""}>${escapeHtml(x.label)}</option>`).join("")}</select></label>`:""}</div><div class="help">Créez vos groupes puis sélectionnez les valeurs qui doivent être consolidées ensemble.</div><div data-grouping-groups>${(g.groups||[]).map(x=>groupingEditorGroupHtml(x,vals)).join("")}</div><button type="button" data-add-group>+ Ajouter un groupe</button></div></details>`}
function groupingFromElement(el){return{id:el.dataset.groupingId||uid('GRP'),name:el.querySelector('[data-grouping-name]')?.value||"",source:el.querySelector('[data-grouping-source]')?.value||"",fallbackSource:el.querySelector('[data-grouping-fallback]')?.value||"",groups:[...el.querySelectorAll('[data-grouping-group]')].map(x=>({id:x.dataset.groupId||uid('VAL'),label:x.querySelector('[data-group-label]')?.value||"",values:[...x.querySelectorAll('[data-group-value]:checked')].map(o=>o.value)}))}}
function builderGroupingsFromForm(){return[...document.querySelectorAll('[data-dashboard-grouping]')].map(groupingFromElement)}
function cloneDashboardGrouping(g,nameSuffix=""){return{id:uid('GRP'),name:`${g?.name||'Regroupement'}${nameSuffix}`,source:g?.source||"",fallbackSource:g?.fallbackSource||"",groups:(g?.groups||[]).map(x=>({id:uid('VAL'),label:x.label||"",values:Array.isArray(x.values)?x.values.map(String):[]}))}}
function dashboardGroupingLibrary(){const out=[];for(const row of(state.loaded.DASHBOARDS||[]).filter(active)){const cfg=dashboardConfig(row);for(const g of normalizeDashboardGroupings(cfg)){if(!g.groups?.length)continue;out.push({key:`dashboard:${row.id}:${g.id}`,origin:"dashboard",label:row.Nom||row.Dashboard_Code||`Dashboard ${row.id}`,grouping:g})}}return out}
function savedGroupingLibrary(){const out=[];for(const row of(state.loaded.BIBLIOTHEQUE_REGROUPEMENTS||[]).filter(active)){let cfg={};try{cfg=JSON.parse(row.Configuration_JSON||"{}")||{}}catch{continue}const normalized=normalizeDashboardGroupings({groupings:[{...cfg,name:cfg.name||row.Nom||"Regroupement",source:cfg.source||row.Source||""}]})[0];if(!normalized?.groups?.length)continue;out.push({key:`library:${row.id}`,origin:"library",label:row.Nom||normalized.name||`Regroupement ${row.id}`,grouping:normalized})}return out}
function groupingLibraryItems(){return[...savedGroupingLibrary(),...dashboardGroupingLibrary()]}
function groupingLibraryOptions(){const lib=savedGroupingLibrary(),dash=dashboardGroupingLibrary();return`${lib.length?`<optgroup label="Bibliothèque">${lib.map(x=>`<option value="${escapeHtml(x.key)}">${escapeHtml(x.label)}</option>`).join("")}</optgroup>`:""}${dash.length?`<optgroup label="Autres Dashboards">${dash.map(x=>`<option value="${escapeHtml(x.key)}">${escapeHtml(x.label)} — ${escapeHtml(x.grouping.name||"Sans nom")}</option>`).join("")}</optgroup>`:""}`}
function importDashboardGrouping(key){const item=groupingLibraryItems().find(x=>x.key===key);if(!item)return null;return cloneDashboardGrouping(item.grouping,item.origin==="library"?"":" (copie)")}
function refreshBuilderGroupings(config={}){const host=document.querySelector('#builder-groupings');if(!host)return;const group=builderCurrentGroup(),items=normalizeDashboardGroupings(config);const library=groupingLibraryOptions();host.innerHTML=`<div class="dashboard-groupings-head"><div><h2>Regroupements</h2><div class="help">Créez des regroupements personnalisés utilisables ensuite dans « Ventilation par ». Vous pouvez aussi importer une copie depuis la bibliothèque ou reprendre un regroupement enregistré dans un autre Dashboard.</div></div><button type="button" id="add-dashboard-grouping">+ Regroupement</button></div>${library?`<div class="dashboard-grouping-library"><label>Réutiliser un regroupement existant<select id="grouping-library-select"><option value="">— Choisir un regroupement —</option>${library}</select></label><button type="button" id="import-dashboard-grouping">Importer une copie</button></div>`:""}<div data-groupings-list>${items.map(g=>groupingEditorHtml(g,group)).join("")}</div>`;bindBuilderGroupings()}
function bindBuilderGroupings(){const host=document.querySelector('#builder-groupings');if(!host)return;host.querySelector('#import-dashboard-grouping')?.addEventListener('click',()=>{const sel=host.querySelector('#grouping-library-select'),g=importDashboardGrouping(sel?.value||"");if(!g){alert('Sélectionnez un regroupement à importer.');return}const list=host.querySelector('[data-groupings-list]');list.insertAdjacentHTML('beforeend',groupingEditorHtml(g,builderCurrentGroup()));list.lastElementChild?.setAttribute('open','');bindBuilderGroupings();refreshAllGroupingVentilations()});host.querySelector('#add-dashboard-grouping')?.addEventListener('click',()=>{const list=host.querySelector('[data-groupings-list]'),group=builderCurrentGroup(),g={id:uid('GRP'),name:'Nouveau regroupement',source:'',groups:[]};list.insertAdjacentHTML('beforeend',groupingEditorHtml(g,group));list.lastElementChild?.setAttribute('open','');bindBuilderGroupings()});host.querySelectorAll('[data-duplicate-grouping]').forEach(btn=>btn.onclick=()=>{const el=btn.closest('[data-dashboard-grouping]'),g=cloneDashboardGrouping(groupingFromElement(el),' (copie)');el.insertAdjacentHTML('afterend',groupingEditorHtml(g,builderCurrentGroup()));el.nextElementSibling?.setAttribute('open','');bindBuilderGroupings();refreshAllGroupingVentilations()});host.querySelectorAll('[data-remove-grouping]').forEach(btn=>btn.onclick=()=>{btn.closest('[data-dashboard-grouping]')?.remove();refreshAllGroupingVentilations()});host.querySelectorAll('[data-grouping-source]').forEach(sel=>sel.onchange=()=>{const el=sel.closest('[data-dashboard-grouping]'),g=groupingFromElement(el);g.source=sel.value;el.outerHTML=groupingEditorHtml(g,builderCurrentGroup());bindBuilderGroupings();refreshAllGroupingVentilations()});host.querySelectorAll('[data-add-group]').forEach(btn=>btn.onclick=()=>{const el=btn.closest('[data-dashboard-grouping]'),src=el.querySelector('[data-grouping-source]')?.value||"",vals=groupingSourceValues(builderCurrentGroup(),src),list=el.querySelector('[data-grouping-groups]');list.insertAdjacentHTML('beforeend',groupingEditorGroupHtml({id:uid('VAL'),label:'',values:[]},vals));list.lastElementChild?.setAttribute('open','');bindBuilderGroupings()});host.querySelectorAll('[data-group-up]').forEach(btn=>btn.onclick=()=>{const e=btn.closest('[data-grouping-group]'),p=e.previousElementSibling;if(p?.matches('[data-grouping-group]'))e.parentNode.insertBefore(e,p)});host.querySelectorAll('[data-group-down]').forEach(btn=>btn.onclick=()=>{const e=btn.closest('[data-grouping-group]'),n=e.nextElementSibling;if(n?.matches('[data-grouping-group]'))e.parentNode.insertBefore(n,e)});host.querySelectorAll('[data-remove-group]').forEach(btn=>btn.onclick=()=>{btn.closest('[data-grouping-group]')?.remove()});host.querySelectorAll('[data-group-values-search]').forEach(input=>input.oninput=()=>{const q=String(input.value||'').trim().toLowerCase(),row=input.closest('[data-grouping-group]');row?.querySelectorAll('[data-group-value-label]').forEach(el=>{el.hidden=!!q&&!String(el.dataset.groupValueLabel||'').includes(q)})});host.querySelectorAll('[data-grouping-name]').forEach(el=>el.oninput=()=>{const card=el.closest('[data-dashboard-grouping]'),label=card?.querySelector('[data-grouping-summary-name]');if(label)label.textContent=el.value||'Nouveau regroupement';refreshAllGroupingVentilations()});host.querySelectorAll('[data-group-label]').forEach(el=>el.oninput=()=>{const row=el.closest('[data-grouping-group]'),label=row?.querySelector('[data-group-summary-label]');if(label)label.textContent=el.value||'Nouveau groupe';refreshAllGroupingVentilations()});host.querySelectorAll('[data-grouping-fallback],[data-group-value]').forEach(el=>el.onchange=()=>refreshAllGroupingVentilations())}
function dashboardGroupingOptions(group,sourceToken,groupings=builderGroupingsFromForm()){const allowed=new Set(ventilationOptions(group,sourceToken).map(x=>x.token));return (groupings||[]).filter(g=>g.source&&allowed.has(g.source)&&g.groups?.length).map(g=>({token:`grp:${g.id}`,label:`Regroupement : ${g.name||'Sans nom'}`,kind:'grouping',grouping:g,q:sourceByToken(group,g.source)?.q}))}
function refreshAllGroupingVentilations(){const group=builderCurrentGroup();document.querySelectorAll('[data-builder-block][data-block-type="indicator"]').forEach(el=>{const sel=el.querySelector('[data-group-by]'),source=el.querySelector('[data-source]')?.value||"",old=sel?.value||"";if(!sel)return;const opts=[...ventilationOptions(group,source),...dashboardGroupingOptions(group,source)];sel.innerHTML=optionHtml(opts,old);if([...sel.options].some(o=>o.value===old))sel.value=old})}

function builderCurrentGroup(){const code=document.querySelector('#builder-campaign')?.value||"";return dashboardGroupRows(state.loaded.CAMPAGNES||[]).find(g=>g.code===code)||null}
function builderTabHtml(tab,group){const title=String(tab.title||"Onglet"),count=(tab.blocks||[]).length;return `<details class="builder-tab" data-dashboard-tab data-tab-id="${escapeHtml(tab.id||uid('TAB'))}"><summary class="builder-collapse-summary builder-tab-summary"><span><strong data-tab-summary-title>${escapeHtml(title)}</strong><small>${count} bloc${count>1?"s":""}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-tab-body"><div class="builder-block-head"><label style="flex:1">Nom de l’onglet<input data-tab-title value="${escapeHtml(title)}"></label><div><button type="button" data-tab-up>↑ Onglet</button><button type="button" data-tab-down>↓ Onglet</button><button type="button" data-remove-tab>Supprimer l’onglet</button></div></div><div class="builder-actions"><button type="button" data-add-text>+ Texte</button><button type="button" data-add-respondents>+ Répondants</button><button type="button" data-add-indicator>+ Indicateur Dashboard</button><button type="button" data-add-reuse>+ Indicateur existant</button></div><div class="builder-blocks" data-tab-blocks>${(tab.blocks||[]).map(b=>builderBlockHtml(b,group)).join("")||'<div class="dash-card muted" data-empty-tab>Aucun bloc dans cet onglet.</div>'}</div></div></details>`}
